df_c = df[df['등급'] == 'C'].copy()
df_c['fail_metal'] = df_c['잔류금속 (wt%)'] > 5.0
df_c['fail_raman'] = df_c['IG/ID'] < 2.2

def get_reason(row):
    if row['fail_metal'] and row['fail_raman']:
        return '둘 다'
    elif row['fail_metal']:
        return '잔류금속 > 5.0 wt%만'
    elif row['fail_raman']:
        return 'IG/ID < 2.2만'
    else:
        return None

df_c['사유'] = df_c.apply(get_reason, axis=1)
df = df_c.dropna(subset=['사유']).copy()
